import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import './App.css'

const DICE_GAME_ADDRESS = "0x..." // Will be filled after deployment
const DICE_GAME_ABI = [
  "function rollDice(uint8 _guessedNumber, bytes32 _userCommitment) payable",
  "function getPlayer(address _player) view returns (uint256 score, uint256 totalRolls, uint256 correctGuesses, uint256 leaderboardPosition)",
  "function getLeaderboard(uint256 _limit) view returns (address[] addresses, uint256[] scores)",
  "function getRandomnessFee() view returns (uint128)",
  "event RollRequested(address indexed player, uint8 guessedNumber, uint64 sequenceNumber)",
  "event RollResult(address indexed player, uint8 guessedNumber, uint8 actualRoll, bool won, uint256 newScore)"
]

function App() {
  const [wallet, setWallet] = useState(null)
  const [contract, setContract] = useState(null)
  const [playerStats, setPlayerStats] = useState({ score: 0, totalRolls: 0, correctGuesses: 0, position: 0 })
  const [leaderboard, setLeaderboard] = useState([])
  const [selectedNumber, setSelectedNumber] = useState(1)
  const [isRolling, setIsRolling] = useState(false)
  const [diceResult, setDiceResult] = useState(null)
  const [lastRollWon, setLastRollWon] = useState(null)
  const [fee, setFee] = useState('0')

  // Dice animation state
  const [animating, setAnimating] = useState(false)
  const [animationFrame, setAnimationFrame] = useState(1)

  useEffect(() => {
    connectWallet()
  }, [])

  const connectWallet = async () => {
    if (typeof window.ethereum !== 'undefined') {
      try {
        await window.ethereum.request({ method: 'eth_requestAccounts' })
        const provider = new ethers.BrowserProvider(window.ethereum)
        const signer = await provider.getSigner()
        const gameContract = new ethers.Contract(DICE_GAME_ADDRESS, DICE_GAME_ABI, signer)

        setWallet(signer)
        setContract(gameContract)

        // Load player stats and fee
        await loadPlayerStats(signer.address, gameContract)
        await loadLeaderboard(gameContract)
        await loadFee(gameContract)

        // Listen for roll results
        gameContract.on("RollResult", (player, guessedNumber, actualRoll, won, newScore) => {
          if (player.toLowerCase() === signer.address.toLowerCase()) {
            setDiceResult(Number(actualRoll))
            setLastRollWon(won)
            setIsRolling(false)
            setAnimating(false)

            // Update stats
            setPlayerStats(prev => ({
              ...prev,
              score: Number(newScore),
              totalRolls: prev.totalRolls + 1,
              correctGuesses: won ? prev.correctGuesses + 1 : prev.correctGuesses
            }))
          }
        })

      } catch (error) {
        console.error('Failed to connect wallet:', error)
      }
    } else {
      alert('Please install MetaMask!')
    }
  }

  const loadPlayerStats = async (address, gameContract) => {
    try {
      const stats = await gameContract.getPlayer(address)
      setPlayerStats({
        score: Number(stats.score),
        totalRolls: Number(stats.totalRolls),
        correctGuesses: Number(stats.correctGuesses),
        position: Number(stats.leaderboardPosition)
      })
    } catch (error) {
      console.error('Failed to load player stats:', error)
    }
  }

  const loadLeaderboard = async (gameContract) => {
    try {
      const [addresses, scores] = await gameContract.getLeaderboard(10)
      const formattedLeaderboard = addresses.map((addr, i) => ({
        address: addr,
        score: Number(scores[i]),
        rank: i + 1
      }))
      setLeaderboard(formattedLeaderboard)
    } catch (error) {
      console.error('Failed to load leaderboard:', error)
    }
  }

  const loadFee = async (gameContract) => {
    try {
      const randomnessFee = await gameContract.getRandomnessFee()
      setFee(ethers.formatEther(randomnessFee))
    } catch (error) {
      console.error('Failed to load fee:', error)
    }
  }

  const rollDice = async () => {
    if (!contract || isRolling) return

    try {
      setIsRolling(true)
      setDiceResult(null)
      setLastRollWon(null)
      startDiceAnimation()

      // Generate random commitment
      const userCommitment = ethers.randomBytes(32)

      // Get current fee and add some buffer
      const currentFee = await contract.getRandomnessFee()
      const feeWithBuffer = currentFee + (currentFee / 10n) // 10% buffer

      const tx = await contract.rollDice(selectedNumber, userCommitment, {
        value: feeWithBuffer
      })

      await tx.wait()
      console.log('Roll requested!')

    } catch (error) {
      console.error('Roll failed:', error)
      setIsRolling(false)
      setAnimating(false)
      alert('Roll failed: ' + error.message)
    }
  }

  const startDiceAnimation = () => {
    setAnimating(true)
    let frame = 1

    const animate = () => {
      if (!isRolling) return

      setAnimationFrame(frame)
      frame = frame === 6 ? 1 : frame + 1

      setTimeout(animate, 150)
    }

    animate()
  }

  const renderDice = (number) => {
    const dots = {
      1: [4],
      2: [0, 8],
      3: [0, 4, 8],
      4: [0, 2, 6, 8],
      5: [0, 2, 4, 6, 8],
      6: [0, 2, 3, 5, 6, 8]
    }

    return (
      <div className="dice">
        {[...Array(9)].map((_, i) => (
          <div
            key={i}
            className={`dot ${dots[number]?.includes(i) ? 'active' : ''}`}
          />
        ))}
      </div>
    )
  }

  return (
    <div className="game-container">
      <header>
        <h1>🎲 DADADDADSADA</h1>
        <p>Verifiable On-Chain Dice Rolling with Pyth Entropy</p>
      </header>

      {!wallet ? (
        <div className="connect-section">
          <button onClick={connectWallet} className="connect-btn">
            Connect Wallet
          </button>
        </div>
      ) : (
        <>
          <div className="player-stats">
            <div className="stat">
              <span className="label">Score:</span>
              <span className="value">{playerStats.score}</span>
            </div>
            <div className="stat">
              <span className="label">Rolls:</span>
              <span className="value">{playerStats.totalRolls}</span>
            </div>
            <div className="stat">
              <span className="label">Wins:</span>
              <span className="value">{playerStats.correctGuesses}</span>
            </div>
            <div className="stat">
              <span className="label">Rank:</span>
              <span className="value">#{playerStats.position || '—'}</span>
            </div>
          </div>

          <div className="game-section">
            <div className="number-selection">
              <h3>Pick a number (1-6):</h3>
              <div className="number-buttons">
                {[1, 2, 3, 4, 5, 6].map(num => (
                  <button
                    key={num}
                    onClick={() => setSelectedNumber(num)}
                    className={`number-btn ${selectedNumber === num ? 'selected' : ''}`}
                    disabled={isRolling}
                  >
                    {num}
                  </button>
                ))}
              </div>
            </div>

            <div className="dice-section">
              <div className="dice-container">
                {animating ? renderDice(animationFrame) : renderDice(diceResult || 1)}
              </div>

              {diceResult && !animating && (
                <div className={`result ${lastRollWon ? 'win' : 'lose'}`}>
                  {lastRollWon ? '🎉 You Won! +100 points' : '😔 Try Again'}
                  <div>You rolled: {diceResult}</div>
                </div>
              )}
            </div>

            <button
              onClick={rollDice}
              disabled={isRolling}
              className="roll-btn"
            >
              {isRolling ? 'Rolling...' : `Roll Dice (${fee} ETH)`}
            </button>
          </div>

          <div className="leaderboard">
            <h3>🏆 Leaderboard</h3>
            {leaderboard.length === 0 ? (
              <p>No players yet. Be the first!</p>
            ) : (
              <div className="leaderboard-list">
                {leaderboard.map((player, i) => (
                  <div key={i} className="leaderboard-item">
                    <span className="rank">#{player.rank}</span>
                    <span className="address">
                      {player.address.slice(0, 6)}...{player.address.slice(-4)}
                    </span>
                    <span className="score">{player.score} pts</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  )
}

export default App

