pragma solidity ^0.8.13;

interface IEntropy {
    function requestRandomness(
        address provider,
        uint128 fee,
        bytes32 userCommitment,
        bool useBlockHash,
        bytes calldata auxData
    ) external payable returns (uint64 sequenceNumber);

    function getFee(address provider) external view returns (uint128 fee);

    function getProviderInfo(address provider) 
        external 
        view 
        returns (uint128 feeInWei, uint128 accruedFeesInWei, bytes32 originalCommitment, uint64 sequenceNumber);
}

interface IEntropyConsumer {
    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external;
}

contract DiceGame is IEntropyConsumer {
    IEntropy public immutable entropy;
    address public immutable entropyProvider;

    struct Player {
        uint256 score;
        uint256 totalRolls;
        uint256 correctGuesses;
    }

    struct PendingRoll {
        address player;
        uint8 guessedNumber;
        uint256 timestamp;
    }

    mapping(address => Player) public players;
    mapping(uint64 => PendingRoll) public pendingRolls;
    address[] public leaderboard;

    event RollRequested(address indexed player, uint8 guessedNumber, uint64 sequenceNumber);
    event RollResult(address indexed player, uint8 guessedNumber, uint8 actualRoll, bool won, uint256 newScore);
    event LeaderboardUpdated(address indexed player, uint256 newScore, uint256 position);

    constructor(address _entropy, address _entropyProvider) {
        entropy = IEntropy(_entropy);
        entropyProvider = _entropyProvider;
    }

    function rollDice(uint8 _guessedNumber, bytes32 _userCommitment) external payable {
        require(_guessedNumber >= 1 && _guessedNumber <= 6, "Invalid number: must be 1-6");

        uint128 fee = entropy.getFee(entropyProvider);
        require(msg.value >= fee, "Insufficient fee for randomness");

        uint64 sequenceNumber = entropy.requestRandomness{value: fee}(
            entropyProvider,
            fee,
            _userCommitment,
            true, // use block hash
            abi.encode(msg.sender, _guessedNumber)
        );

        pendingRolls[sequenceNumber] = PendingRoll({
            player: msg.sender,
            guessedNumber: _guessedNumber,
            timestamp: block.timestamp
        });

        emit RollRequested(msg.sender, _guessedNumber, sequenceNumber);

        // Refund excess payment
        if (msg.value > fee) {
            payable(msg.sender).transfer(msg.value - fee);
        }
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external override {
        require(msg.sender == address(entropy), "Only entropy contract can call");
        require(provider == entropyProvider, "Invalid provider");

        PendingRoll memory roll = pendingRolls[sequenceNumber];
        require(roll.player != address(0), "Invalid sequence number");

        // Convert random number to dice roll (1-6)
        uint8 diceResult = uint8((uint256(randomNumber) % 6) + 1);

        // Update player stats
        Player storage player = players[roll.player];
        player.totalRolls++;

        bool won = (diceResult == roll.guessedNumber);
        if (won) {
            player.score += 100;
            player.correctGuesses++;
            _updateLeaderboard(roll.player);
        }

        emit RollResult(roll.player, roll.guessedNumber, diceResult, won, player.score);

        // Clean up
        delete pendingRolls[sequenceNumber];
    }

    function _updateLeaderboard(address playerAddr) internal {
        Player memory player = players[playerAddr];

        // Check if player is already on leaderboard
        bool found = false;
        uint256 currentPosition = 0;

        for (uint256 i = 0; i < leaderboard.length; i++) {
            if (leaderboard[i] == playerAddr) {
                found = true;
                currentPosition = i;
                break;
            }
        }

        if (!found) {
            // Add new player to leaderboard
            leaderboard.push(playerAddr);
            currentPosition = leaderboard.length - 1;
        }

        // Bubble sort to maintain order (highest score first)
        for (uint256 i = currentPosition; i > 0; i--) {
            if (players[leaderboard[i]].score > players[leaderboard[i-1]].score) {
                // Swap positions
                address temp = leaderboard[i];
                leaderboard[i] = leaderboard[i-1];
                leaderboard[i-1] = temp;
            } else {
                break;
            }
        }

        // Find final position
        uint256 finalPosition = 0;
        for (uint256 i = 0; i < leaderboard.length; i++) {
            if (leaderboard[i] == playerAddr) {
                finalPosition = i;
                break;
            }
        }

        emit LeaderboardUpdated(playerAddr, player.score, finalPosition + 1);
    }

    function getPlayer(address _player) external view returns (
        uint256 score,
        uint256 totalRolls,
        uint256 correctGuesses,
        uint256 leaderboardPosition
    ) {
        Player memory player = players[_player];
        score = player.score;
        totalRolls = player.totalRolls;
        correctGuesses = player.correctGuesses;

        leaderboardPosition = 0;
        for (uint256 i = 0; i < leaderboard.length; i++) {
            if (leaderboard[i] == _player) {
                leaderboardPosition = i + 1;
                break;
            }
        }
    }

    function getLeaderboard(uint256 _limit) external view returns (
        address[] memory addresses,
        uint256[] memory scores,
        uint256[] memory totalRolls
    ) {
        uint256 length = _limit > leaderboard.length ? leaderboard.length : _limit;

        addresses = new address[](length);
        scores = new uint256[](length);
        totalRolls = new uint256[](length);

        for (uint256 i = 0; i < length; i++) {
            addresses[i] = leaderboard[i];
            Player memory player = players[leaderboard[i]];
            scores[i] = player.score;
            totalRolls[i] = player.totalRolls;
        }
    }

    function getRandomnessFee() external view returns (uint128) {
        return entropy.getFee(entropyProvider);
    }

    // Allow owner to withdraw accumulated entropy fees (if any)
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}"}

