  background: #4f46e5;
  color: white;
  border-color: #4f46e5;
  transform: scale(1.1);
}

.number-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.dice-section {
  margin: 3rem 0;
}

.dice-container {
  display: flex;
  justify-content: center;
  margin-bottom: 2rem;
}

.dice {
  width: 120px;
  height: 120px;
  background: #fff;
  border: 4px solid #333;
  border-radius: 15px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  gap: 5px;
  padding: 10px;
  box-shadow: 0 8px 25px rgba(0,0,0,0.2);
  transition: transform 0.1s ease;
}

.dice:hover {
  transform: scale(1.05);
}

.dot {
  border-radius: 50%;
  transition: all 0.2s ease;
}

.dot.active {
  background: #333;
}

.result {
  padding: 1.5rem;
  border-radius: 15px;
  font-size: 1.3rem;
  font-weight: 600;
  animation: slideIn 0.5s ease;
}

.result.win {
  background: linear-gradient(45deg, #10b981, #34d399);
  color: white;
}

.result.lose {
  background: linear-gradient(45deg, #ef4444, #f87171);
  color: white;
}

.roll-btn {
  background: linear-gradient(45deg, #4f46e5, #7c3aed);
  color: white;
  border: none;
  padding: 1.5rem 3rem;
  font-size: 1.3rem;
  font-weight: 700;
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 6px 25px rgba(79,70,229,0.4);
}

.roll-btn:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(79,70,229,0.6);
}

.roll-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.leaderboard {
  background: white;
  padding: 3rem;
  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(0,0,0,0.1);
}

.leaderboard h3 {
  text-align: center;
  margin-bottom: 2rem;
  color: #333;
  font-size: 2rem;
}

.leaderboard-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.leaderboard-item {
  display: grid;
  grid-template-columns: 60px 1fr auto;
  gap: 1rem;
  padding: 1.5rem;
  background: #f8fafc;
  border-radius: 12px;
  align-items: center;
  transition: all 0.2s ease;
}

.leaderboard-item:hover {
  background: #f1f5f9;
  transform: translateY(-1px);
}

.leaderboard-item:first-child {
  background: linear-gradient(45deg, #fbbf24, #f59e0b);
  color: white;
}

.leaderboard-item:nth-child(2) {
  background: linear-gradient(45deg, #94a3b8, #64748b);
  color: white;
}

.leaderboard-item:nth-child(3) {
  background: linear-gradient(45deg, #cd7c2f, #b45309);
  color: white;
}

.rank {
  font-weight: 800;
  font-size: 1.2rem;
}

.address {
  font-family: 'Monaco', 'Menlo', monospace;
  font-weight: 500;
}

.score {
  font-weight: 700;
  font-size: 1.1rem;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .game-container {
    padding: 1rem;
  }

  header h1 {
    font-size: 2rem;
  }

  .game-section, .leaderboard {
    padding: 2rem 1rem;
  }

  .number-buttons {
    gap: 0.5rem;
  }

  .number-btn {
    width: 50px;
    height: 50px;
    font-size: 1.2rem;
  }

  .dice {
    width: 100px;
    height: 100px;
  }
}"}

