    address public immutable entropyProvider;

    struct Player {
        uint256 score;
        uint256 totalRolls;
        uint256 correctGuesses;
    }

    struct PendingRoll {
        address player;
        uint8 guessedNumber;
        uint256 timestamp;
    }

